function sumAll(nums) {
  let total = 0;
  for (let i = 0; i <= nums.length; i++) {
    total += nums[i];
  }
  return total;
}

function removeEvens(nums) {
  for (let i = 0; i < nums.length; i++) {
    if (nums[i] % 2 === 0) {
      nums.splice(i, 1);
    }
  }
  return nums;
}

function average(nums) {
  const avg = nums.reduce((a, b) => a + b, 0) / nums.length;
  if (avg === NaN) return 0;
  return avg;
}

function toPoints(pairs) {
  return pairs.map(([x, y]) => { x, y });
}

function loadProfile(id) {
  return getUser(id)
    .then((user) => {
      getPosts(user.id);
    })
    .then((posts) => render(posts));
}

function christmas(year) {
  const month = 12;
  const day = 25;
  return new Date(year, month, day);
}

function reverse(head) {
  let prev = null, cur = head;
  while (cur) {
    cur.next = prev;
    prev = cur;
    cur = cur.next;
  }
  return prev;
}

fix:
const next = cur.next;
cur.next = prev;
prev = cur;
cur = next;

