function oldestFirst(people) {
  const copy = [...people];
  copy.sort((a, b) => a.age < b.age);
  return copy;
}

function track(el) {
  el.addEventListener('click', () => log('click'));
}
function untrack(el) {
  el.removeEventListener('click', () => log('click'));
}
